using Aegis.Studio.Application.Abstractions;
namespace Aegis.Studio.Infrastructure.Storage;
public sealed class LocalMediaStorage:IMediaStorage{private readonly string root;public LocalMediaStorage(){string localData=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);root=Path.Combine(localData,"Aegis.Studio","media");Directory.CreateDirectory(root);}public async Task<string> SaveAsync(string fileName,Stream content,CancellationToken cancellationToken){string key=$"{Guid.NewGuid():N}{Path.GetExtension(fileName)}";await using FileStream output=File.Create(Path.Combine(root,key));await content.CopyToAsync(output,cancellationToken);return key;}public Task<Stream> OpenReadAsync(string storageKey,CancellationToken cancellationToken){Stream stream=File.OpenRead(Path.Combine(root,Path.GetFileName(storageKey)));return Task.FromResult(stream);}}
